CATEGORY_CODE = {
    "furniture": "FUR", "home decor": "DEC", "kitchen": "KIT", "clothing": "CLO",
    "fashion": "FAS", "electronics": "ELE", "books": "BOK", "sports": "SPT",
}
CONDITION_LABEL = {"Good": "Good", "Medium": "Fair", "Worst": "Needs refurbishing"}


def carry_over(apps, schema_editor):
    """Stock the old table held (donated items) becomes inventory: still at the dock if it is
    in the warehouse, or released as a donation if it was given out."""
    Item = apps.get_model("warehouse", "WarehouseItem")
    Event = apps.get_model("warehouse", "WarehouseEvent")
    for w in Item.objects.select_related("donation", "donation__user").order_by("pk"):
        given = w.status == "Given_Out"
        w.warehouse_status = "Released" if given else "Received"
        w.sale_status = "Donated" if given else "Not listed"
        w.condition = CONDITION_LABEL.get(w.condition, w.condition)
        if given:
            w.released_at = w.given_at or w.received_at
        else:
            w.zone, w.rack, w.level = "DOCK", "01", 1
        donor = getattr(w.donation, "user", None) if w.donation_id else None
        if donor is not None:
            w.source_user = donor
            w.source_name = donor.full_name
            w.source_sub = donor.email
            w.purchase_ref = w.donation.public_id or ""
        number = "".join(ch for ch in (w.public_id or "") if ch.isdigit()) or str(w.pk)
        w.sku = f"RO-{CATEGORY_CODE.get((w.category or '').strip().lower(), 'GEN')}-{number}"
        w.save()
        Event.objects.create(
            item=w, label="Received at warehouse", tone="good", at=w.received_at,
            detail=f"Donated by {w.source_name} · {w.purchase_ref}" if w.source_name else "Donated item",
        )
        if given:
            Event.objects.create(item=w, label="Donated", tone="neutral", at=w.released_at,
                                 detail=(w.given_to or "Given to a partner") + " · Admin")


def carry_back(apps, schema_editor):
    Item = apps.get_model("warehouse", "WarehouseItem")
    for w in Item.objects.all():
        gone = w.warehouse_status == "Released"
        w.status = "Given_Out" if gone else "In_Stock"
        w.given_at = w.released_at if gone else None
        w.location = "Main warehouse"
        w.save()


